const entries=[...document.querySelectorAll(".entry")];
const project={index:document.querySelector("#project-index"),state:document.querySelector("#project-state"),command:document.querySelector("#project-command"),name:document.querySelector("#project-name"),path:document.querySelector("#project-path"),description:document.querySelector("#project-description"),tags:document.querySelector("#project-tags"),action:document.querySelector("#project-action"),actionLabel:document.querySelector("#project-action-label")};
function inspect(entry){entries.forEach(candidate=>{const active=candidate===entry;candidate.classList.toggle("is-active",active);candidate.setAttribute("aria-pressed",String(active))});project.index.textContent=entry.dataset.index;project.state.textContent=entry.dataset.state;project.command.textContent=entry.dataset.name.toLowerCase();project.name.textContent=entry.dataset.name;project.path.textContent=entry.dataset.path;project.description.textContent=entry.dataset.description;project.tags.textContent=entry.dataset.tags;const hasAction=Boolean(entry.dataset.url);project.action.hidden=!hasAction;if(hasAction){project.action.href=entry.dataset.url;project.actionLabel.textContent=entry.dataset.action}}
entries.forEach((entry,index)=>{entry.addEventListener("click",()=>inspect(entry));entry.addEventListener("keydown",event=>{if(!["ArrowRight","ArrowLeft","ArrowDown","ArrowUp"].includes(event.key))return;event.preventDefault();const direction=["ArrowRight","ArrowDown"].includes(event.key)?1:-1;const next=entries[(index+direction+entries.length)%entries.length];next.focus();inspect(next)})});
const clock=document.querySelector("#utc-clock");function updateClock(){clock.textContent=`${new Date().toISOString().slice(11,19)} UTC`}updateClock();setInterval(updateClock,1000);document.querySelector("#year").textContent=new Date().getUTCFullYear();
